using System.IO;using System.Net.Http;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;
namespace AulaControlTeacher;
public class ViewerWindow:Window{readonly Device d;readonly string key;readonly Image img=new(){Stretch=Stretch.Uniform};readonly TextBlock state=new(){Foreground=Brushes.LightGray};readonly HttpClient http=new(){Timeout=TimeSpan.FromSeconds(2)};readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(850)};public ViewerWindow(Device x,string k){d=x;key=k;Title="AulaControl · "+d.Name;Width=900;Height=760;Background=new SolidColorBrush(Color.FromRgb(15,23,42));var g=new Grid();g.RowDefinitions.Add(new RowDefinition{Height=new GridLength(52)});g.RowDefinitions.Add(new RowDefinition());var h=new DockPanel{Margin=new Thickness(14,8,14,8)};var name=new TextBlock{Text=$"{d.Name} · {d.Person} · {d.Id}",Foreground=Brushes.White,FontSize=18,FontWeight=FontWeights.SemiBold,VerticalAlignment=VerticalAlignment.Center};DockPanel.SetDock(state,Dock.Right);h.Children.Add(state);h.Children.Add(name);g.Children.Add(h);var b=new Border{Background=Brushes.Black,Margin=new Thickness(12),CornerRadius=new CornerRadius(8),Child=img};Grid.SetRow(b,1);g.Children.Add(b);Content=g;timer.Tick+=async(_,_)=>await Refresh();Loaded+=async(_,_)=>{timer.Start();await Refresh();};Closed+=(_,_)=>{timer.Stop();http.Dispose();};}async Task Refresh(){try{long ts=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();using var q=new HttpRequestMessage(HttpMethod.Get,$"http://{d.Ip}:{d.ScreenPort}/screen.jpg");q.Headers.Add("X-Timestamp",ts.ToString());q.Headers.Add("X-Signature",AcCrypto.Hmac(key,$"SCREEN\n{ts}"));var r=await http.SendAsync(q);if(!r.IsSuccessStatusCode){state.Text="Esperando…";return;}byte[] z=await r.Content.ReadAsByteArrayAsync();using var ms=new MemoryStream(z);var bi=new BitmapImage();bi.BeginInit();bi.CacheOption=BitmapCacheOption.OnLoad;bi.StreamSource=ms;bi.EndInit();bi.Freeze();img.Source=bi;state.Text="● En vivo";}catch{state.Text="Reconectando…";}}}
public class MosaicWindow:Window{readonly List<Device> ds;readonly string key;readonly HttpClient http=new(){Timeout=TimeSpan.FromSeconds(2)};readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromMilliseconds(1300)};readonly Dictionary<string,Image> imgs=new();readonly Dictionary<string,TextBlock> states=new();bool busy;public MosaicWindow(List<Device> d,string k){ds=d;key=k;Title="AulaControl · Mosaico";Width=1280;Height=820;Background=new SolidColorBrush(Color.FromRgb(15,23,42));var wrap=new WrapPanel{Margin=new Thickness(10)};Content=new ScrollViewer{Content=wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};foreach(var x in ds){var border=new Border{Width=390,Height=290,Margin=new Thickness(8),Background=new SolidColorBrush(Color.FromRgb(2,6,23)),CornerRadius=new CornerRadius(10),BorderBrush=new SolidColorBrush(Color.FromRgb(51,65,85)),BorderThickness=new Thickness(1)};var g=new Grid();g.RowDefinitions.Add(new RowDefinition{Height=new GridLength(42)});g.RowDefinitions.Add(new RowDefinition());var head=new DockPanel{Margin=new Thickness(12,6,12,6)};var s=new TextBlock{Text="Conectando…",Foreground=Brushes.LightGray};DockPanel.SetDock(s,Dock.Right);head.Children.Add(s);head.Children.Add(new TextBlock{Text=x.Name+" · "+x.Person,Foreground=Brushes.White,FontWeight=FontWeights.SemiBold});g.Children.Add(head);var im=new Image{Stretch=Stretch.Uniform};Grid.SetRow(im,1);g.Children.Add(im);border.Child=g;wrap.Children.Add(border);imgs[x.Id]=im;states[x.Id]=s;border.MouseLeftButtonDown+=(_,_)=>new ViewerWindow(x,key){Owner=this}.Show();}timer.Tick+=async(_,_)=>await Refresh();Loaded+=async(_,_)=>{timer.Start();await Refresh();};Closed+=(_,_)=>{timer.Stop();http.Dispose();};}async Task Refresh(){if(busy)return;busy=true;try{await Task.WhenAll(ds.Select(Fetch));}finally{busy=false;}}async Task Fetch(Device d){try{long ts=DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();using var q=new HttpRequestMessage(HttpMethod.Get,$"http://{d.Ip}:{d.ScreenPort}/screen.jpg");q.Headers.Add("X-Timestamp",ts.ToString());q.Headers.Add("X-Signature",AcCrypto.Hmac(key,$"SCREEN\n{ts}"));var r=await http.SendAsync(q);if(!r.IsSuccessStatusCode){states[d.Id].Text="Esperando…";return;}byte[] z=await r.Content.ReadAsByteArrayAsync();using var ms=new MemoryStream(z);var bi=new BitmapImage();bi.BeginInit();bi.CacheOption=BitmapCacheOption.OnLoad;bi.DecodePixelWidth=360;bi.StreamSource=ms;bi.EndInit();bi.Freeze();imgs[d.Id].Source=bi;states[d.Id].Text="● En vivo";}catch{states[d.Id].Text="Sin señal";}}}
